#!/usr/bin/env python3
"""campaign-link-check: deterministic gate for App Store campaign links (pt/ct).
Stdlib only, offline, free. Sources (read in full 2026-11-23):
- Tayyab, "App Store Campaign Links: The Indie Attribution Checklist" (dev.to,
  orig. iamtayyab.com), citing App Store Connect Help as primary:
  https://dev.to/iamtayyab/app-store-campaign-links-the-indie-attribution-checklist-2lee
  A campaign link is the normal apps.apple.com URL plus pt (provider token,
  generated by Apple in App Store Connect, same for every campaign/app, cannot
  be invented), ct (campaign token, <=30 chars, letters/numbers/spaces/listed
  punctuation, no leading/trailing space) and mt=8 as generated. Attribution:
  first-time download within 24h of the tap; most recent campaign tap wins.
  One link per PLACEMENT, not per platform; tag the creator, not just the
  platform; scheme channel_placement_date; keep a ledger of every ct, where it
  lives and when it went live. Link straight to apps.apple.com (every redirect
  hop via shortener/link-in-bio is a place attribution breaks; for Safari web
  referrer only the LAST URL before the store gets credit, so the button itself
  must carry the ct). Test each link on a real iPhone inside each host app.
  Reading: metrics appear only at >=5 in the selected range and after >=24h;
  widen the range (30+ days) before calling a channel dead; untagged traffic
  lands undifferentiated in Web/App Referrer; search absorbs viewers who saw
  the name and typed it later, so cross-check search lift on posting days.
  Smart App Banner ct/pt syntax is NOT in Apple's current banner docs --
  treat as unverified until seen in own campaign data. Combining ct with a
  custom product page ppid is undocumented -- verify both record before
  relying on it. Cross-promo inside own apps uses SKStoreProductViewController
  with the same provider/campaign token parameters (owned by crosspromo-check
  for the placement decision; this gate owns the token discipline itself).
Delimitation: crosspromo-check owns in-app cross-promotion placement,
ad-attribution-check owns paid/ATT attribution, cpp-check owns custom product
pages, deferred-link-check owns deferred deep links. This gate owns the
campaign-token discipline of every external store link the company controls.
Exit 0 = PASS, 1 = FAIL. Input JSON keys are the check names (booleans).
"""
import json, sys
CHECKS = [
    ("link_inventory_recorded", "CL-0 no inventory of controlled store links exists (every place the company links to its apps -- site, bios, pinned posts, email footer, video descriptions, QR codes -- listed per app; an unlisted link cannot be tagged or audited)"),
    ("pt_obtained_from_app_store_connect", "CL-0 the provider token was not obtained from App Store Connect (pt is generated by Apple when the first campaign link is created; an invented or copied pt means the campaign never appears in App Analytics)"),
    ("pt_recorded_once_and_reused", "CL-0 the pt is not recorded once as a shared constant (pt is identical for every campaign and app; re-deriving or varying it per link breaks the one attribution identity)"),
    ("every_controlled_link_tagged", "CL-0 at least one controlled store link is still a bare apps.apple.com URL with no ct (untagged taps land undifferentiated in Web/App Referrer and the channel that caused them can never be read)"),
    ("ct_within_30_chars_and_charset", "CL-1 a campaign token exceeds 30 characters or uses characters outside Apple's set / leading-trailing spaces (an invalid ct fails silently -- no error, just lost attribution)"),
    ("mt8_preserved_as_generated", "CL-1 mt=8 was dropped or altered from the link as App Store Connect generated it (leave the media type exactly as generated; hand-edited parameters are silent-breakage surface)"),
    ("one_ct_per_placement_not_per_platform", "CL-2 one ct is shared across placements (a bio link and a story link on the same platform are two campaigns; one shared token merges every channel into a single undifferentiated row)"),
    ("creators_tagged_individually", "CL-2 creator/affiliate links are tagged by platform only, not by the individual creator (the unit that gets renewed or cut is the person; platform-level tags cannot price a creator)"),
    ("naming_scheme_channel_placement_date", "CL-2 ct values do not follow a consistent channel_placement_date scheme (with 30 characters the scheme is the memory; ad-hoc names like x2_alt are unreadable six weeks later)"),
    ("ct_ledger_with_location_and_live_date", "CL-2 no ledger records every ct, where it lives and when it went live (the ledger is what turns a token string into a decision input; without it campaign rows in App Analytics are orphans)"),
    ("links_direct_to_apps_apple_com", "CL-3 a store link routes through a shortener, link-in-bio service or third-party tracker (each hop is a place blockers, in-app browsers and bot filters break attribution; Apple's link needs none of them)"),
    ("button_itself_carries_ct", "CL-3 the ct sits on an intermediate landing hop instead of the final store button (for Safari, only the last URL before the App Store gets Web Referrer credit -- a tracker domain in between takes the credit)"),
    ("links_tested_on_device_in_host_apps", "CL-3 links were never tested on a real iPhone inside each host app they live in (in-app browsers credit differently and preview-bot rules can serve a card instead of the redirect; desktop Safari testing proves nothing)"),
    ("read_in_30day_windows_after_24h", "CL-4 campaigns are read day-by-day or before 24h (new campaigns appear after >=24h and small numbers move slowly; the documented routine is first-time downloads by campaign over 30+ day ranges)"),
    ("threshold_5_respected_no_premature_kill", "CL-4 a channel was judged dead below Apple's reporting threshold (each metric shows only at >=5 in range and a campaign appears after 5 distinct first-time downloaders; below that, a dead channel and a slow one look identical)"),
    ("last_click_and_24h_window_in_reading", "CL-4 readings ignore last-click-wins and the 24h window (a later campaign tap overwrites the earlier one, and a tap that converts via search 3 days later is a search download -- campaigns are not cleanly separate audiences)"),
    ("search_lift_crosschecked_on_posting_days", "CL-4 campaign readings are never cross-checked against search lift (viewers who saw the app name and typed it into search are credited to Search; posting-day search lift is the honest second signal, not a contradiction)"),
    ("unverified_surfaces_not_relied_on", "CL-5 an undocumented surface is treated as verified (Smart App Banner ct/pt syntax is absent from Apple's current banner docs, and ct+ppid combination is undocumented -- both stay unverified until they appear in the company's own campaign data)"),
]
def check(d):
    return [m for k, m in CHECKS if not d.get(k)]
def main():
    d = json.load(open(sys.argv[1]))
    fails = check(d)
    for f in fails: print("FAIL", f)
    print(f"RESULT: {'PASS' if not fails else 'FAIL'} ({len(CHECKS)-len(fails)}/{len(CHECKS)} checks passed, {len(fails)} fails)")
    sys.exit(0 if not fails else 1)
if __name__ == "__main__": main()
